import{_ as t,o as e,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse(`{"title":"CommonJS 和 ESModule（ESM）","description":"CommonJS 和 ESModule（ESM） 是两种 JavaScript 模块化标准，常见于 Node.js 和现代浏览器环境。下面是它们的主要区别： 1. 引入方式 CommonJS const fs require('fs'); ESModule import fs f。","frontmatter":{"title":"CommonJS 和 ESModule（ESM）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"CommonJS 和 ESModule（ESM） 是两种 JavaScript 模块化标准，常见于 Node.js 和现代浏览器环境。下面是它们的主要区别： 1. 引入方式 CommonJS const fs require('fs'); ESModule import fs f。","sidebarWeight":1,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/CommonJS 和 ESModule（ESM）/CommonJS 和 ESModule（ESM）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/CommonJS 和 ESModule（ESM）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/CommonJS 和 ESModule（ESM）.md"}`),n={name:"posts/JavaScript系统教程/06-模块化与工程化/CommonJS 和 ESModule（ESM）/CommonJS 和 ESModule（ESM）.md"};function d(l,o,m,S,a,i){return e(),r("div",null,[...o[0]||(o[0]=[s('<div><h1 id="commonjs-和-esmodule-esm" tabindex="-1">CommonJS 和 ESModule（ESM） <a class="header-anchor" href="#commonjs-和-esmodule-esm" aria-label="Permalink to &quot;CommonJS 和 ESModule（ESM）&quot;">​</a></h1><blockquote><p>本节目标：理解“CommonJS 和 ESModule（ESM）”的核心思路，并能把它用于实际开发或面试表达。 CommonJS 和 ESModule（ESM） 是两种 JavaScript 模块化标准，常见于 Node.js 和现代浏览器环境。下面是它们的主要区别：</p></blockquote><p><strong>1. 引入方式</strong></p><ul><li><strong>CommonJS</strong>****const fs = require(&#39;fs&#39;);</li><li><strong>ESModule</strong>****import fs from &#39;fs&#39;;</li></ul><p><strong>2. 导出方式</strong></p><ul><li><strong>CommonJS</strong>****module.exports = { a, b };</li><li><strong>ESModule</strong>****export const a = 1;export default function() {}</li></ul><p><strong>3. 加载机制</strong></p><ul><li><strong>CommonJS</strong> 是<strong>同步加载</strong>，适用于服务器端。</li><li><strong>ESModule</strong> 是<strong>异步加载</strong>，适用于浏览器环境，也被 Node.js 支持。</li></ul><p><strong>4. 执行时机</strong></p><ul><li><strong>CommonJS</strong> 是<strong>立即执行</strong>，require 是运行时加载。</li><li><strong>ESModule</strong> 是<strong>静态分析</strong>，import 是编译时加载（提升作用）。</li></ul><p><strong>5. 默认导出差异</strong></p><ul><li>CommonJS 的 module.exports 是一个对象或函数</li><li>ESM 的 export default 是真正的默认导出</li></ul><p><strong>6. 兼容性</strong></p><ul><li>CommonJS 是 Node.js 默认模块系统（但新版本已支持 ESM）</li><li>ESM 是浏览器原生支持、Node.js 的新标准模块系统</li></ul><p><strong>7. 文件扩展名</strong></p><ul><li>CommonJS 通常是 .js</li><li>ESM 通常是 .mjs 或在 package.json 中设置 &quot;type&quot;: &quot;module&quot;</li></ul><p><strong>总结对比表：</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>CommonJS</strong></td><td><strong>ESModule</strong></td></tr><tr><td>语法</td><td>require / module.exports</td><td>import / export</td></tr><tr><td>加载方式</td><td>同步</td><td>异步</td></tr><tr><td>执行时机</td><td>运行时</td><td>编译时</td></tr><tr><td>默认导出</td><td>module.exports = xxx</td><td>export default xxx</td></tr><tr><td>使用场景</td><td>Node.js（旧）</td><td>Node.js（新）和浏览器</td></tr></tbody></table><p>如果你是在 Node.js 项目中开发：</p><ul><li>默认使用 CommonJS</li><li>可以通过配置 ESM 来启用 import/export（如设置 &quot;type&quot;: &quot;module&quot;）</li></ul><p>需要我根据你当前项目类型具体说明使用哪种更合适也可以告诉我。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const g=t(n,[["render",d]]);export{p as __pageData,g as default};
